export const archiveSurvey = async (surveyId) => {
  return await prisma.$transaction(async (tx) => {
    const survey = await tx.survey.findUnique({ where: { id: surveyId }, select: { id: true, status: true, archivedAt: true } });
    if (!survey) throw new ResourceNotFoundError('Survey', surveyId);
    if (survey.archivedAt) return survey;
    return await tx.survey.update({ where: { id: surveyId }, data: { archivedAt: new Date(), ...(survey.status === 'inProgress' ? { status: 'paused' } : {}) }, select: { id: true, status: true, archivedAt: true } });
  });
}

